pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // We fuzz a caller address (as an index seed) and a uint256 salt-ish value to create variability.
    // The adversarial helper will call initialize and, during execution, attempt to observe c.initialized()
    // by using a reentrant check via a callback invoked by the factory event flow — to reliably observe
    // initialized() while initialize is still in-progress in the mutant we simulate the caller as a contract
    // that calls initialize and then immediately reads initialized() after the call returns. The distinguishing
    // behaviour: reference always returns with initialized()==true, mutant may return with initialized()==false.
    function testFuzz_property(address callerSeed, uint256 paramSeed) public {
        // Keep domains wide but avoid the zero address for the helper owner (not necessary but safe)
        if (callerSeed == address(0)) callerSeed = address(1);

        // Deploy a helper that will call initialize on c and then read initialized() immediately after the call returns.
        CallerHelper helper = new CallerHelper(c);

        // Prepare pseudo-randomized parameters derived from fuzz inputs to avoid hard-coding.
        address _baseToken = address(uint160(uint256(keccak256(abi.encodePacked(callerSeed, paramSeed, "base")))));
        address _nft = address(uint160(uint256(keccak256(abi.encodePacked(callerSeed, paramSeed, "nft")))));
        uint128 _vBase = uint128(uint256(keccak256(abi.encodePacked(callerSeed, paramSeed, "vbase"))) & type(uint128).max);
        uint128 _vNft = uint128(uint256(keccak256(abi.encodePacked(callerSeed, paramSeed, "vnft"))) & type(uint128).max);
        uint56 _changeFee = uint56(uint256(keccak256(abi.encodePacked(callerSeed, paramSeed, "chg"))) & type(uint56).max);
        uint16 _feeRate = uint16(uint256(keccak256(abi.encodePacked(callerSeed, paramSeed, "fee"))) & type(uint16).max);
        bytes32 _merkleRoot = keccak256(abi.encodePacked(callerSeed, paramSeed, "root"));
        bool _useStolen = (uint256(keccak256(abi.encodePacked(callerSeed, paramSeed, "use"))) & 1) == 1;
        bool _payRoyalties = (uint256(keccak256(abi.encodePacked(callerSeed, paramSeed, "pay"))) & 1) == 1;

        // Ensure feeRate stays within allowed bounds so initialize doesn't revert for that reason in either contract.
        _feeRate = _feeRate % 5001; // 0..5000 allowed

        // Instruct helper to call initialize with these parameters and report whether after the call returns
        // c.initialized() observed by an external call to the helper equals true.
        bool observedInitTrue = helper.callInitializeAndRead(
            _baseToken,
            _nft,
            _vBase,
            _vNft,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolen,
            _payRoyalties
        );

        // The universal property: for any admissible parameters that made initialize return normally,
        // the reference contract ensures initialized() == true after the call returns. We assert that
        // our call observed initialized()==true. This holds on the reference for all inputs, and the mutant
        // (which sets initialized = true after emit) can return while initialized()==false for some inputs,
        // causing this assertion to fail for those cases.
        assertTrue(observedInitTrue);
    }
}

/// @notice Helper contract that calls initialize on target C and then reads c.initialized() immediately after.
contract CallerHelper {
    C public target;

    constructor(C _target) { target = _target; }

    // Calls initialize on target and returns the post-call value of target.initialized().
    function callInitializeAndRead(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) external returns (bool) {
        // Perform the external call; let it revert if parameters invalid — test only concerns successful returns.
        // We intentionally do not catch revert to keep behaviour aligned with reference (reverts means test input
        // not admissible for the universal property).
        target.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );

        // Immediately read the public getter for initialized and return it to the fuzzer.
        return target.initialized();
    }
}

