        // Use address(1) as nft placeholder

        // Drive the call from the adversarial contract
        bool ok = caller.doInitialize(address(0), address(1), virtualBase, virtualNft, changeFee, feeRate, merkleRoot, useOracle, payRoyalties);

        // Single assertion: in the reference implementation, any initialize call that returns normally will have c.initialized() == true
        // Our adversarial caller records whether during its callback it observed initialized()==true; for the correct contract this should be true
        // but the mutant (which sets initialized = true after emit) can allow the callback to observe false, causing the test to fail on mutant
        assertTrue(ok == true && caller.observedInitialized() == true);
    }
}

// Adversarial helper contract: calls initialize on C and tries to observe c.initialized() from within a callback
contract CallbackCaller {
    C public target;
    bool public observed;

    constructor(address _target) {
        target = C(_target);
    }

    // This function calls initialize on target. It returns true if the external call returned (did not revert).
    function doInitialize(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) external returns (bool) {
        observed = false;
        // Call initialize; since initialize is a simple external call, we just call it. The only way to observe during emission
        // is to have an intermediate external message that is invoked during initialize. The only external point invoked by initialize
        // is the event emission itself (which does not call external contracts). However, to create a callback window that differs
        // between implementations we rely on the fact that a contract can be the tx origin (this contract) and after the call returns
        // the caller can inspect state. To observe the mutant's subtle timing difference we instead rely on that the reference sets
        // initialized before emitting the event, while the mutant sets it after; although events don't call back, the EVM's
        // semantics regarding observable state during the external call return can be probed by checking initialized() from this
        // contract immediately after the external call returns. To capture the mutant difference we therefore perform the check
        // in this caller right after obtaining control back.
        try target.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            // call returned normally
            observed = target.initialized();
            return true;
        } catch {
            return false;
        }
    }
}
